import * as React from 'react';
import ContactsIcon from '@mui/icons-material/Contacts';
import FacebookIcon from '@mui/icons-material/Facebook';
import InstagramIcon from '@mui/icons-material/Instagram';
import LinkedInIcon from '@mui/icons-material/LinkedIn';
import GitHubIcon from '@mui/icons-material/GitHub';
import MailIcon from '@mui/icons-material/Mail';
import { Box, SpeedDial, SpeedDialAction } from '@mui/material';

const actions = [
    { icon: <FacebookIcon />, name: 'Facebook', link: 'https://www.facebook.com/john.michael.ong.037/' },
    { icon: <InstagramIcon />, name: 'Instagram', link: 'https://www.instagram.com/john.michael.ong/' },
    { icon: <MailIcon />, name: 'Email', link: 'mailto:jhonlance.37@gmail.com' },
    { icon: <GitHubIcon />, name: 'GitHub', link: 'https://github.com/jmong143' },
    { icon: <LinkedInIcon />, name: 'LinkedIn', link: 'https://www.linkedin.com/in/john-michael-ong-3b2428b5' }
];

export default function Socials() {

    return (
        <Box sx={{ transform: 'translateZ(0px)', flexGrow: 1 }}>
            <SpeedDial
                ariaLabel="SpeedDial basic example"
                sx={{ position: 'absolute', bottom: 16, right: 16 }}
                icon={<ContactsIcon />}
            >
                {actions.map((action) => (
                    <SpeedDialAction
                        key={action.name}
                        icon={action.icon}
                        tooltipTitle={action.name}
                        onClick={(e) => window.open(action.link, '_blank')}
                    />
                ))}
            </SpeedDial>
        </Box>
    );
}
