
import { Box, Container, Typography } from "@mui/material";

interface BioProps {
    overview?: string;
    description?: string;
}

export default function Bio(props: BioProps) {
    return (
        <Box sx={{ backgroundColor: '#83B4FF' }}>
            <Container maxWidth="lg" sx={{ textAlignLast: 'center' }}>
                <Box sx={{ paddingTop: 10, paddingBottom: 10 }}>
                    <Typography variant="h5" sx={{ fontWeight: 'bold', padding: 3, textAlign: 'justify' }}>
                        {props.overview}
                    </Typography>
                    <Typography variant="body1" sx={{ textAlign: 'justify' }}>
                        {props.description}
                    </Typography>
                </Box>

            </Container>
        </Box>
    )
}