
import * as React from "react";
import { useLocation, useNavigate } from "react-router-dom";
import { Alert, Box, Button, Chip, Collapse, Container, SpeedDial, SpeedDialAction, SpeedDialIcon, Stack, TextField, ThemeProvider, Typography } from "@mui/material";
import Navbar from "../../components/Navbar";
import { theme } from "../../theme";
import { contactUsApi } from "../../storage";

interface ContactProps {
    overview?: string;
    description?: string;
}

export default function Contact(props: ContactProps) {
    const location = useLocation();
    const [name, setName] = React.useState<string>('');
    const [email, setEmail] = React.useState<string>('');
    const [subject, setSubject] = React.useState<string>('');
    const [message, setMessage] = React.useState<string>('');
    const [open, setOpen] = React.useState(false);
    const [disabled, setDisabled] = React.useState(false);

    const handleSendMessage = async (e: any) => {
        e.preventDefault();
        setDisabled(true);
        const formData = {
            to: 'jhonlance.37@gmail.com',
            from: email,
            subject: `[PORTFOLIO Email] - ${subject}`,
            text: message,
            html: `<div> <h3>Name:</h3> ${name} </div> <div> <h3>Message: </h3> ${message} </div>`
        }
        await contactUsApi.post<Response>('/email/send', formData).then(() => {
            setOpen(true);
            setDisabled(false);
        });
    }
    return (
        <ThemeProvider theme={theme}>
            {location.pathname !== "/" && <Navbar />}
            <Box sx={{ backgroundColor: location.pathname === "/" ? '#edf3fc' : '' }}>
                <Container maxWidth="lg" sx={{ textAlign: 'center' }}>
                    <Box sx={{ paddingTop: 10, paddingBottom: 10 }}>
                        <Typography variant="h5" sx={{ fontWeight: 'bold', padding: 3, textAlign: 'justify' }}>
                            Contact Me
                        </Typography>

                        <Collapse in={open}>
                            <Box sx={{ paddingBottom: 5 }}>
                                <Alert severity="success" onClose={() => setOpen(!open)}>
                                    Successfully sent email!
                                </Alert>
                            </Box>
                        </Collapse>

                        <Typography variant="body1" sx={{ textAlign: 'center' }}>
                            If you’d like to chat about a project or just have question, you can reach me by fill up the form below. I aim to get back within 2 days.
                        </Typography>
                        <Box
                            component="form"
                            sx={{
                                '& .MuiTextField-root': { m: 1 },
                            }}
                            noValidate
                            autoComplete="off"
                        >
                            <div>
                                <TextField
                                    id="name"
                                    name="name"
                                    label="Name"
                                    sx={{
                                        width: '40%',
                                        textAlign: 'left'
                                    }}
                                    onChange={(e) => setName(e.target.value)}
                                />
                                <TextField
                                    id="email"
                                    name="email"
                                    type="email"
                                    label="Email"
                                    sx={{
                                        width: '40%',
                                        textAlign: 'left'
                                    }}
                                    onChange={(e) => setEmail(e.target.value)}
                                />
                            </div>
                            <div>
                                <TextField
                                    id="subject"
                                    name="subject"
                                    type="subject"
                                    label="Subject"
                                    sx={{
                                        width: '80%',
                                        textAlign: 'left'
                                    }}
                                    onChange={(e) => setSubject(e.target.value)}
                                />
                            </div>

                            <div>
                                <TextField
                                    id="message"
                                    name="message"
                                    type="message"
                                    label="Message"
                                    rows={4}
                                    multiline
                                    sx={{
                                        width: '80%',
                                        textAlign: 'left'
                                    }}
                                    onChange={(e) => setMessage(e.target.value)}
                                />
                            </div>
                            <Button variant="contained" disabled={disabled} type="submit" onClick={handleSendMessage}>Send Message</Button>

                        </Box>

                        {/* <Box sx={{ paddingTop: 5, paddingBottom: 10 }}>
                            <Typography variant="body1" sx={{ textAlign: 'center' }}>
                                Also, you can reach out to me to my socials:
                            </Typography>
                            <Stack direction={{ xs: 'column', sm: 'row' }} spacing={1} sx={{ justifyContent: 'center' }}>
                                <Chip
                                    label="LinkedIn"
                                    component="a"
                                    target="_blank"
                                    icon={<LinkedInIcon />}
                                    href='www.linkedin.com/in/john-michael-ong-3b2428b5'
                                    variant="filled"
                                    clickable
                                />
                                <Chip
                                    label="Email (gmail)"
                                    component="a"
                                    icon={<MailIcon />}
                                    href='mailto:jhonlance.37@gmail.com'
                                    variant="filled"
                                    clickable
                                />
                                <Chip
                                    label="Instagram"
                                    component="a"
                                    target="_blank"
                                    icon={<InstagramIcon />}
                                    href='https://www.instagram.com/john.michael.ong/'
                                    variant="filled"
                                    clickable
                                />
                                <Chip
                                    label="Facebook"
                                    component="a"
                                    target="_blank"
                                    icon={<FacebookIcon />}
                                    href='https://www.facebook.com/john.michael.ong.037/'
                                    variant="filled"
                                    clickable
                                />
                            </Stack>
                        </Box> */}
                    </Box>

                </Container>
            </Box>
        </ThemeProvider>
    )
}